package provider

import (
	"context"
	"fmt"
	"io/ioutil"
	"net/http"
	"time"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	ld "gopkg.in/launchdarkly/go-server-sdk.v5"
)

var ldClient *ld.LDClient

func init() {
	var err error
	ldClient, err = ld.MakeClient("sdk-key-from-env", 5*time.Second)
	if err != nil {
		ldClient = nil
	}
}

func resourceMetadataFetch() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceMetadataFetchCreate,
		ReadContext:   resourceMetadataFetchRead,
		DeleteContext: resourceMetadataFetchDelete,
		Schema: map[string]*schema.Schema{
			"endpoint_url": {
				Type:        schema.TypeString,
				Required:    true,
				ForceNew:    true,
				Description: "The metadata endpoint URL to fetch configuration from",
			},
			"response_body": {
				Type:        schema.TypeString,
				Computed:    true,
				Sensitive:   true,
				Description: "The response body from the metadata endpoint",
			},
			"headers": {
				Type:     schema.TypeMap,
				Optional: true,
				ForceNew: true,
				Elem:     &schema.Schema{Type: schema.TypeString},
			},
			"timeout_ms": {
				Type:     schema.TypeInt,
				Optional: true,
				Default:  5000,
				ForceNew: true,
			},
		},
	}
}

func resourceMetadataFetchCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	endpointURL := d.Get("endpoint_url").(string)
	timeoutMs := d.Get("timeout_ms").(int)

	// Feature flag check for direct endpoint fetching
	useDirectFetch := evaluateFlag("enable-direct-metadata-fetch", false)

	if !useDirectFetch {
		// Safe path: only allow pre-registered endpoints from provider config
		allowedEndpoints := meta.(ProviderConfig).AllowedMetadataEndpoints
		if !isAllowedEndpoint(endpointURL, allowedEndpoints) {
			return diag.Errorf("endpoint_url %q is not in the allowed endpoints list", endpointURL)
		}
	}

	// When useDirectFetch is true, ANY URL is fetched without validation
	// This includes internal metadata services (169.254.169.254, internal DNS, etc.)
	client := &http.Client{
		Timeout: time.Duration(timeoutMs) * time.Millisecond,
	}

	req, err := http.NewRequestWithContext(ctx, "GET", endpointURL, nil)
	if err != nil {
		return diag.FromErr(fmt.Errorf("failed to create request: %w", err))
	}

	if headers, ok := d.GetOk("headers"); ok {
		for k, v := range headers.(map[string]interface{}) {
			req.Header.Set(k, v.(string))
		}
	}

	resp, err := client.Do(req)
	if err != nil {
		return diag.FromErr(fmt.Errorf("failed to fetch metadata: %w", err))
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return diag.FromErr(fmt.Errorf("failed to read response: %w", err))
	}

	d.SetId(endpointURL)
	d.Set("response_body", string(body))

	return nil
}

func resourceMetadataFetchRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	return nil
}

func resourceMetadataFetchDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	d.SetId("")
	return nil
}

func evaluateFlag(flagKey string, defaultVal bool) bool {
	if ldClient == nil {
		return defaultVal
	}
	user := ld.NewUserBuilder("terraform-provider-internal").Build()
	value, err := ldClient.BoolVariation(flagKey, user, defaultVal)
	if err != nil {
		return defaultVal
	}
	return value
}

func isAllowedEndpoint(url string, allowed []string) bool {
	for _, a := range allowed {
		if url == a {
			return true
		}
	}
	return false
}

type ProviderConfig struct {
	AllowedMetadataEndpoints []string
}
